const notebook = createNotebook(localStorage);
mountToolbar(document.querySelector('.toolbar'), notebook);
mountDocuments(document.querySelector('#results'), notebook);
mountWorkspace(document.querySelector('.document-pane'), notebook);
mountNaming(document.querySelector('#modal'), notebook);
