app/state.js:
const storageKey = 'fieldnotes.notebook.v1';
const initialDocuments = [
  {id: 'coastal', title: 'Coastal survey', text: "Coastal survey\n\nThe north path follows the estuary.\nRecord the water level before leaving.\nBring the map and a second battery.\nCompare the evening observations.\nThe south gate closes at dusk.\n\nNotes from the field team:\nArrive before the tide turns.\nUse the marked crossing near the bridge.\nCheck the return route before sunset.\nKeep the sample labels dry.\nMeet at the station at six.", preferences: {format:'Plain text', sharing:'Only me'}},
  {id: 'equipment', title: 'Equipment list', text: 'Map\nSecond battery\nSample labels', preferences: {format:'Plain text', sharing:'Only me'}}
];

export function createNotebook(storage) {
  const stored = storage.getItem(storageKey);
  let saved;
  try { saved = JSON.parse(stored); } catch { saved = null; }
  const state = saved?.documents?.length ? saved : {documents: initialDocuments, activeId: 'coastal'};
  const listeners = new Set();
  let query = '', dialog = null, saveState = 'idle';
  const persist = () => storage.setItem(storageKey, JSON.stringify(state));
  const notify = event => listeners.forEach(listener => listener(event));
  const current = () => state.documents.find(doc => doc.id === state.activeId);
  return {
    get documents() { return state.documents; },
    get current() { return current(); },
    get query() { return query; },
    get dialog() { return dialog; },
    get saveState() { return saveState; },
    subscribe(listener) { listeners.add(listener); return () => listeners.delete(listener); },
    search(value) { query = value; notify('search'); },
    select(id) { state.activeId = id; saveState = 'idle'; persist(); notify('document'); },
    edit(text) { current().text = text; persist(); },
    openDialog(mode) { dialog = {mode, title: mode === 'new' ? '' : current().title, touched:false, error:''}; notify('dialog'); },
    closeDialog() { dialog = null; notify('dialog'); },
    name(value) { dialog.title = value; if (dialog.touched) dialog.error = value.trim() ? '' : 'Enter a document name.'; notify('name'); },
    confirmName() {
      dialog.touched = true;
      dialog.error = dialog.title.trim() ? '' : 'Enter a document name.';
      if (dialog.error) { notify('name'); return; }
      if (dialog.mode === 'new') {
        const id = crypto.randomUUID();
        state.documents.push({id, title:dialog.title.trim(), text:'', preferences:{format:'Plain text', sharing:'Only me'}});
        state.activeId = id;
      } else current().title = dialog.title.trim();
      dialog = null; saveState = 'idle'; persist(); notify('document'); notify('dialog');
    },
    applyPreference(key, value) { current().preferences[key] = value; persist(); notify('preference'); },
    save() { saveState = 'failed'; notify('save'); },
    retry() {
      saveState = 'saving'; notify('save');
      setTimeout(() => { saveState = 'saved'; persist(); notify('save'); }, 1200);
    }
  };
}

