export function mountToolbar(root, notebook) {
  root.innerHTML = `<div class="action-group" id="document-actions"><button id="new">New document</button><button id="rename">Rename</button></div>
<div class="action-group" id="filter-actions"><label for="search">Find</label><input id="search" type="search" placeholder="Find a document"><button id="clear">Clear</button></div>`;
  root.querySelector('#new').onclick = () => notebook.openDialog('new');
  root.querySelector('#rename').onclick = () => notebook.openDialog('rename');
  root.querySelector('#search').oninput = event => notebook.search(event.target.value);
  root.querySelector('#clear').onclick = () => { root.querySelector('#search').value = ''; notebook.search(''); };
}

