export function mountNaming(root, notebook) {
  root.innerHTML = `<section class="dialog-frame" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-heading"><span class="document-mark" aria-hidden="true">F</span><h2 id="dialog-title"></h2></header>
<form id="name-form"><label for="name">Document name</label><input id="name" autocomplete="off"><p id="name-error" class="feedback-slot" role="alert"></p><footer id="modal-actions"><button type="button" id="cancel">Cancel</button><button type="submit" id="confirm"></button></footer></form></section>`;
  const input = root.querySelector('#name');
  const render = event => {
    const dialog = notebook.dialog;
    root.hidden = !dialog;
    if (!dialog) return;
    root.querySelector('#dialog-title').textContent = dialog.mode === 'new' ? 'New document' : 'Rename document';
    root.querySelector('#confirm').textContent = dialog.mode === 'new' ? 'Create' : 'Rename';
    root.querySelector('#name-error').textContent = dialog.error;
    if (event === 'dialog') { input.value = dialog.title; input.focus(); }
  };
  root.querySelector('#cancel').onclick = () => notebook.closeDialog();
  input.oninput = event => notebook.name(event.target.value);
  root.querySelector('#name-form').onsubmit = event => { event.preventDefault(); notebook.confirmName(); };
  notebook.subscribe(event => { if (['dialog','name'].includes(event)) render(event); });
}

