export function mountEditor(editor, notebook) {
  editor.classList.add('document-text');
  editor.value = notebook.current.text;
  editor.oninput = event => notebook.edit(event.target.value);
  notebook.subscribe(event => { if (event === 'document') editor.value = notebook.current.text; });
}

