import { mountEditor } from './editor.js';
import { mountSaveStatus } from './save-status.js';

export function mountWorkspace(root, notebook) {
  root.innerHTML = `<header class="document-heading"><h2 id="document-title"></h2><button id="save">Save</button></header>
<section id="save-notice" class="save-notice" aria-live="polite" hidden><div class="notice-top"><strong id="save-label"></strong><button id="retry" hidden>Retry</button></div><p id="save-detail"></p></section>
<textarea class="code-editor text-entry" aria-label="Document text" spellcheck="false"></textarea>
<footer class="document-footer"><span>Saved locally</span><span>Plain text</span></footer>`;
  const render = () => { root.querySelector('#document-title').textContent = notebook.current.title; };
  mountEditor(root.querySelector('.code-editor'), notebook);
  mountSaveStatus(root, notebook);
  notebook.subscribe(event => { if (event === 'document') render(); });
  render();
}

